export type LayoutCheckParams = {
  board?: Id;
  ids?: Id[];
  rect?: Frame;
  caller?: Id;
};
export type LayoutCheckResult = {
  overlaps: Id[][];
  arrowCrossings: {
    arrow: Id;
    crosses: Id[];
  }[];
  labelOverlaps: {
    arrow: Id;
    /** the caption as drawn */
    label: string;
    /** where the label chip is drawn (an arrow's own frame leaves it out) */
    frame: Frame;
    /** objects under the label; an arrow id means that arrow's label, a group id that group's title */
    overlaps: Id[];
    /** other arrows whose line runs under the label */
    lines: Id[];
  }[];
  /** pairs of arrows drawn on top of each other (collinear within 3 points): readers can't tell them apart there */
  arrowOverlaps: {
    arrows: Id[];
    /** points of shared length */
    length: number;
    /** the middle of the first shared run */
    at: {
      x: number;
      y: number;
    };
  }[];
  /** pairs of arrows whose lines cross; fewer read better, and moving a tile or reordering a column often removes them */
  arrowIntersections: {
    arrows: Id[];
    count: number;
    /** the first crossing */
    at: {
      x: number;
      y: number;
    };
  }[];
  overflow: {
    id: Id;
    x: number;
    y: number;
  }[];
  /** code tiles whose range's rows (wrapped at the frame's width) are `y` points taller than the frame: they scroll to the range */
  scrolls: {
    id: Id;
    y: number;
  }[];
  /** text the frame's width cuts off with "…": a code tile's caption, or a note's table with more columns than the note has room for even with its cells wrapped */
  truncated: ({
    id: Id;
    what: "caption" | "table";
    /** points of width missing to show all of it */
    x: number;
  })[];
  /** present when there is advice that isn't a fault: more than 6 labelled arrows all one color (label chips are outlined in their arrow's color, so one color can't show which line a label names): color arrows by lane or flow */
  hints?: string[];
};

