/** Every API method, grouped by namespace (`api.board.get(...)`). */
export interface CanvasApi {
  system: {
    /** Liveness and schema version. */
    ping(params?: SystemPingParams): Promise<SystemPingResult>;
  };
  app: {
    /** What easl's own work costs, for finding what makes it slow: main-thread busy time and stretches (with the longest one's cause), per-method API requests (`api.<method>`: requests answered, time from arrival to the queued reply, waiting behind earlier requests on the connection included, and reply bytes; `api.in.<method>` requests arrived and their bytes; `api.main.<method>` the main-thread part of its dispatches), events sent, board writes and group refits (top writers), arrow routings (`route.board` the whole board, `route.arrow` one arrow following its ends; top triggering objects), saves, live tiles per kind, HTML page loads, reuses, measures and renders, and the process's CPU, wakeups, memory and energy with its WebKit helpers'. Counters cover three windows: since launch or the last reset, the last 60 s, the last 10 min. `easl metrics [--watch] [--reset]` prints them as text. */
    metrics(params?: AppMetricsParams): Promise<AppMetricsResult>;
  };
  board: {
    /** Board manifest: all objects plus a change cursor. Heavy props are summarized (use object.get for them whole): HTML `html` and a follow tile's `history` become a short string, note `markdown` past 400 characters is cut. Objects created or changed since `since` are flagged. */
    get(params?: BoardGetParams): Promise<BoardGetResult>;
    /** Activity log: who created, changed, or deleted what (including objects that existed only for seconds), where the user's viewport settled, what they selected, follow-tile re-aims, and app starts. Plain request/response, cheap to poll: pass the returned `cursor` as `since` next time. In memory, newest 2000 entries per board; an app restart starts a new log with a `restart` entry. */
    history(params?: BoardHistoryParams): Promise<BoardHistoryResult>;
    /** Every stored board, open or not, including archived boards whose root directory is gone. */
    list(params?: BoardListParams): Promise<BoardListResult>;
    /** Open the board for a directory (creating it if new) as a tab of the frontmost board window, also when that window is minimized (the tab waits there). A directory in a git repository opens the repository's board (one per repository, rooted at its main checkout), tagged with the worktree it is in: the window names it, New Terminal starts there, and the view goes to its region. The user's current tab stays in front unless `select` is true, which also brings a minimized window back. Opening an already-open board only selects it when `select` is true. */
    open(params: BoardOpenParams): Promise<BoardOpenResult>;
    /** Write a pretty-printed JSON snapshot of an open board (objects, frames, props; not the personal selection tray) into the repo. Committing it is left to the caller. */
    export(params?: BoardExportParams): Promise<BoardExportResult>;
  };
  object: {
    /** Read one object. `as: graph` adds structural relations: encloses, enclosedBy, overlaps, arrowsIn/arrowsOut (arrows bound to it), arrows (arrows drawn inside it, with from/to bindings), and from/to for an arrow. A changes tile adds `changes`: its files and hunks as git has them now (what the user kept), each hunk with its unified `lines`, next to `props.reviewed` (what they staged or discarded, with the patches). A terminal adds `lastCommand` once its shell finished one. A browser tile adds `page`: the console messages, uncaught errors and failed requests its page reported since it loaded (recorded from the first line of the page on), its error and warning counts, and web vitals; pass `page.cursor` back as `since` to read only what came after. A note adds `fences`: each anchored fence's state (live, relocated, stale, applied, missing), resolved range and reason, resolved against disk now; a code tile showing a range adds `rangeStatus`, the same for its range. To look at an object, `view.render` it. */
    get(params: ObjectGetParams): Promise<ObjectGetResult>;
    /** Find objects by what they are instead of by id: `key` returns the object holding that `props.key` (ObjectKey) as object.get does (`as: graph` too), or `not_found`; `keyPrefix` lists every object whose key starts with it, in key order ("REL-" for every ticket's region), possibly none; `type` lists every object of that type, oldest first, and with `status` only those whose `props.status` is it (`type: question, status: open`: the questions still waiting on the user). One of key, keyPrefix, type. Per board: `board` defaults as for object.create. */
    find(params?: ObjectFindParams): Promise<ObjectFindResult>;
    /** Create an object. Omit `frame` (or give only its `w` and `h`) to let the board place it in the free spot nearest the calling agent's terminal (or the viewport center for users): clear of every tile and group, inside the user's view when the terminal is on screen and there's room within 600 pt of it (else beside it, even out of view). `size: fit` sizes the frame to the content (object.measure; notes and text wrap at `frame.w`; code is at most `frame.w` wide, default 960, and wraps longer lines; html is `frame.w` wide, default 640, and as tall as its page at that width, at most 4000; changes shows every hunk, as wide as its longest line up to `frame.w`, default 960, longer lines wrapped, at most 4000 tall, and a fitted changes tile grows with its diff; image is its picture at one point per pixel, scaled down to at most `frame.w`, default 960, plus the title bar and caption; a diagram is its graph: one without `props.graph` is computed first, waiting for the language server up to 60 s as object.reload does, then fitted, and `diagram` says how that went). A note without a frame height is always fitted to its markdown (at `frame.w`, default 280), and an image to its picture, so `frame` may be just x, y, w (or omitted). A note's line-range fences (`file=…#L…`) are stored with the `anchor=` their tile would write back, so the result's `rev` is the one to update with. The caller's tile (EASL_TILE_ID) becomes createdBy. A changes tile the calling agent already made for the same `root`, `base`, and `paths` is reused rather than duplicated: it takes the call's other props, `frame`, and `size`, and the result says `reused: true`. */
    create(params: ObjectCreateParams): Promise<ObjectCreateResult>;
    /** Patch an object's frame and/or props (shallow merge). `frame` may give any of x, y, w, h; the rest stay. Pass `rev` for optimistic concurrency (a note's fences are anchored as on create). `size: fit` re-measures the frame from the (patched) content at its current position and width (code and image: at most `frame.w`, default 960, never its current width), or at `frame` x, y, w. Without `frame` x or y it doesn't grow over objects it didn't already overlap: it grows up and/or left instead (keeping its bottom or right edge), else moves to the nearest free spot no farther than its longer side, else grows in place (the result's `overlaps` names what it covers). After changing an html tile's `html` or a note's `markdown`, pass `size: "fit"` in the same update to refit its height to the new content. */
    update(params: ObjectUpdateParams): Promise<ObjectUpdateResult>;
    /** Create or update by key, so a script that rebuilds part of the board (a region per ticket) can run again and again without keeping ids: when an object on the board holds `key` it is updated (`props` shallow-merged, `frame` and `size` as object.update; its type must be `type`, else `conflict`), else one is created as object.create would with `key` added to its props. Either way the result names the object's id; `created` says which happened. In object.batch, later ops can name it as "$n" either way, and an upsert of a key an earlier op of the batch creates updates that one. */
    upsert(params: ObjectUpsertParams): Promise<ObjectUpsertResult>;
    /** Delete an object (and remove it from any staged mentions). Arrows bound to it keep their drawn route: that end becomes a free `point` where it last attached. */
    delete(params: ObjectDeleteParams): Promise<ObjectDeleteResult>;
    /** Intrinsic size: the whole frame (tile title bar included, exactly the box the tile draws) that shows the content without scrolling. code: exactly `range` (or the symbol, or the whole file), as wide as its longest line up to `width` (default 960) with longer lines soft-wrapped and counted in the height, with the caption strip when `caption` is set, and wide enough for the whole caption up to that same maximum (a longer caption truncates); note: the rendered markdown (live fences resolved) at `width` (default 280); shape: text at `width` (default one unwrapped line per paragraph), rect/ellipse around their text; html: `width` wide (default 640) and as tall as the page's document laid out at that width, once it has rendered (Mermaid, excerpts), at most 4000 (a longer page scrolls; layout.check reports the rest); changes: the file list and every file and hunk row under its header (deleted and viewed files folded, as the tile starts), as wide as the longest line up to `width` (default 960, at least 480), longer lines wrapped, at most 4000 tall; image: its picture at one point per pixel, at most `width` (default 960) wide, plus the caption strip (`not_found` when the file isn't a readable image). A tile with `zoom` lays out at `width` ÷ zoom, and its frame is the 26-pt title bar plus that body times zoom (as wide as its natural width times zoom). Other types are `unsupported`. */
    measure(params: ObjectMeasureParams): Promise<ObjectMeasureResult>;
    /** Load a browser tile's page again, as its reload button does (the same address, Back history untouched; a failed load is retried): any browser tile, including one the user or `object.create` made. Waits until the page has loaded or `timeoutMs` passes, so an `easl get <tile> --since <cursor>` right after reads the new page's log (`reloaded: true`). The page changes that follow are credited to `caller` in `board.history`. A diagram tile is computed again from the code (its nodes re-resolved by symbol; gone ones badged stale), waiting up to `timeoutMs` (default 60000: a language server's first answers in a project take a while); the result counts nodes and names the stale ones, and `object.get` has the graph (`props.graph`). Only browser and diagram tiles reload: code, note and changes tiles follow their files by themselves. */
    reload(params: ObjectReloadParams): Promise<ObjectReloadResult>;
    /** Apply several changes atomically: one board revision and one undo step, and if any op fails nothing changes (the error names the op). Ops are object.create/update/upsert/delete and layout.place/stack/translate/grid with their usual params; the string "$n" anywhere in an op's params stands for the id op n created (or, an upsert, created or updated) (e.g. an arrow from "$0" to "$1", a group with members ["$0", "$1"], a grid cell {"id": "$2", "row": 0, "col": 1}). */
    batch(params: ObjectBatchParams): Promise<ObjectBatchResult>;
  };
  layout: {
    /** Move an object `gap` points beside another (one undo step). Groups move their members; arrows follow their bound ends. */
    place(params: LayoutPlaceParams): Promise<LayoutPlaceResult>;
    /** Lay objects out in a row (left to right) or column (top to bottom), `gap` apart, starting where the first one is or at `origin` (one undo step). With `wrapAt`, a line longer than that many points wraps into a new line. Groups move as a whole, so stacking groups lays out lanes. */
    stack(params: LayoutStackParams): Promise<LayoutStackResult>;
    /** Move objects by (dx, dy) in one undo step. Groups move with their members (a member listed beside its group moves once), arrows carry their free ends, and arrows bound to moved objects follow. For build-offscreen-then-swap: create a layout far away in a batch, then translate it into place. */
    translate(params: LayoutTranslateParams): Promise<LayoutTranslateResult>;
    /** Place objects in shared columns and rows (one undo step): a column is as wide as its widest cell and a row as tall as its tallest, measured from the cells' current frames, `colGap`/`rowGap` apart, so columns line up across rows even when the cells belong to different groups (their groups re-fit). Row and column numbers only order cells; unused numbers take no space. Groups as cells move whole. Leave `rowGap` room for group padding and title bands between rows of different groups. */
    grid(params: LayoutGridParams): Promise<LayoutGridResult>;
    /** Layout problems for `ids`, for what intersects `rect`, or for the whole board, judged by what is drawn (a tile's frame is its whole box, title bar included; arrows route as drawn, line-bound ends at their lines): overlapping objects (a group and its members don't count; unfilled rects/ellipses are annotations and never overlap anything), arrows whose route runs through tiles, text, or filled shapes other than their own ends, arrow labels lying on a tile, text, or filled shape (their own ends included), a group's title, another label, or another arrow's line, arrows drawn on top of each other (`arrowOverlaps`: shared length) or crossing each other (`arrowIntersections`), note/text/html whose content doesn't fit its frame (`overflow`: points missing in x and y; html: its page's document laid out at the frame's width), code tiles whose range's rows are taller than the frame (`scrolls`: the tile scrolls to its range, fine for a viewer meant to scroll; refit with `size: "fit"` when the whole range should show), and code captions or note tables cut off by the frame (`truncated`; a note's table cells wrap within its width, so only a table with too many columns for it is cut). Follow tiles are fixed-size viewers and never count as overflow or truncated. */
    check(params?: LayoutCheckParams): Promise<LayoutCheckResult>;
  };
  tray: {
    /** Staged mentions, in staging order. */
    list(params?: TrayListParams): Promise<TrayListResult>;
    /** Stage a mention (normally done by the user with Hyper-click; exposed for tests and agents). */
    stage(params: TrayStageParams): Promise<TrayStageResult>;
    /** Remove one staged mention. */
    unstage(params: TrayUnstageParams): Promise<TrayUnstageResult>;
    /** Resolve all staged mentions at their current revision and return them with a ready-to-inject context block. By default the tray is cleared; with `peek: true` it is left intact so the caller can `tray.commit` exactly these ids once the context has really been delivered (a cancelled prompt then loses nothing). The tray's mentions are for the terminal it shows (the board's prompt target, `view.get` `promptTarget`): a `caller` tile that isn't that terminal gets none of them, the tray stays as it is, and `held` says how many wait for `target`. Without a caller (a script) or while the board has no window, the tray drains to anyone. A `caller` also gets the mentions other agents attached for it with `agent.prompt` `mentions` (never shown in the tray), after the tray's, in a block per sending terminal (`<canvas-mentions … from="obj_…">` and a line naming it); `tray.commit` of their ids removes them too. In the context, a mention of the caller's own terminal says `(your terminal)`; other terminals are named (their `name`, else title). `prompt` is the text the caller's agent integration is about to submit (its submission drain, the text as the agent passes it). Compared folded (letters and digits only, case-folded), so an agent's rewrites don't matter: when it contains the text of a prompt the user sent the caller from easl's composer with mentions (the oldest such; a folded text under 3 characters must equal it), the drain is that prompt's and takes the mentions it carried (numbered from 1) instead of the tray (`tray.commit` of their ids ends the wait). An answer Codex submits as a prompt is matched the same way and takes nothing. Any other drain takes the tray as described. */
    drain(params?: TrayDrainParams): Promise<TrayDrainResult>;
    /** Remove exactly these mentions from the tray after their context was delivered (second half of a `peek` drain). Unknown ids are ignored. */
    commit(params: TrayCommitParams): Promise<TrayCommitResult>;
  };
  agent: {
    /** Report lifecycle state for the agent running in a terminal tile. Stale `seq` values from the same source are ignored. With `call`, `blocked` means that tool call waits for the user's approval and `working` that it finished: while any reported call waits, the tile stays `blocked` (with the oldest waiting call's message) whatever other calls finish; finishing it re-raises the next one. With `serial`, a `blocked` call replaces every earlier wait (agents that ask one approval at a time), so the message always names the request on screen. `working` without `call` (a new prompt) and `idle` end every wait. `unknown`: an agent without a lifecycle integration runs in the tile (a wrapper such as `bin/aider` reports it as the agent starts): the tile counts as an agent for the tray and `agent.wait`, and its terminal notifications report when it waits (lifecycle `via: "notifications"`). */
    report(params: AgentReportParams): Promise<AgentReportResult>;
    /** Report the agent's native session identity so the tile can resume it after a reboot. */
    report_session(params: AgentReportSessionParams): Promise<AgentReportSessionResult>;
    /** The agent in this tile exited; clear its lifecycle authority and its recorded session (`agent.report_session`), so after a reboot the tile runs its `command` (a plain shell when it has none) instead of resuming that session. */
    release(params: AgentReleaseParams): Promise<AgentReleaseResult>;
    /** Every terminal tile across all open boards, with the agent in it: a terminal whose agent never reported (a shell, a CLI without easl hooks) has kind and lifecycle `unknown`. An agent without an integration that sends terminal notifications (aider through easl's `aider` wrapper, any CLI's OSC 9/777 or bell) is listed with its program as `kind` and a lifecycle `via: "notifications"`: `done` when it last said it waits, `unknown` after a prompt until it says so again, never `working` or `blocked`. */
    list(params?: AgentListParams): Promise<AgentListResult>;
    /** Paste a prompt into another agent's terminal (bracketed paste; a one-line command into a shell at its prompt is typed) and press Enter once the paste has landed (80 ms later: TUIs such as Gemini CLI take an Enter right after input as part of it). The terminal's text just before submitting is remembered, so `agent.read` with `since: "prompt"` returns only what followed. `agent.wait` after it ignores the state the agent was in before this prompt: it answers once the agent has reported `working` (or `blocked`) and then reached one of its `until` states, so wait for `done` right away, not for `working` first. A prompt that lands while the agent is `working` joins that turn (omp and Codex take it before the turn ends and answer it in the same turn): the wait answers when that turn ends, and `final` is that turn's answer. A `blocked` target fails with `conflict` naming what it waits on (an approval dialog or question would take the text) unless `force` is true. So does a `working` target whose state is `restored` (from before the app last closed, unconfirmed since: it may wait on a question now). So does a target whose agent reports from behind another foreground program (`program` nvim, less: the text would go to that program), and one in tmux whose active pane runs something else (vim, a shell): the text goes to the active pane, so it is sent when that pane runs the agent. Into a shell at its prompt (no agent), a one-line text is typed rather than pasted. `mentions` attach board objects for the receiving agent the way the user's Hyper-click mentions do: they wait for that terminal only (never in the user's tray), and its integration attaches them, resolved then, as hidden context to the next prompt it submits (this one), in a block naming your terminal (`caller`). The target must run an agent with an easl integration (its lifecycle not `via: "notifications"`), else `unavailable`. An agent reporting by notification goes `unknown` with this prompt, and `agent.wait` answers at its next notification (none comes when the text needed no model reply, e.g. aider's `/add`: give such waits a `timeoutMs`). */
    prompt(params: AgentPromptParams): Promise<AgentPromptResult>;
    /** Wait until the target agent reaches one of the given states. After `agent.prompt` it waits for that prompt's turn (see agent.prompt); one that starts no turn within 60 s (its agent reports neither `working` nor `blocked`: a `/` command or `!` escape is no turn) fails it with `unavailable`, so read what followed with `agent.read` `since: "prompt"`. A terminal whose lifecycle is `unknown` gets 15 s for a first report (an agent just launched in it) and then fails with `unavailable`, as does one whose agent exits, unless `until` includes `unknown`; an agent reporting by notification (lifecycle `via: "notifications"`) waits for its next notification instead. A read: when the connection drops mid-wait (the app restarts), clients re-send it once the app is back, with `timeoutMs` reduced by the time already waited. */
    wait(params: AgentWaitParams): Promise<AgentWaitResult>;
    /** Recent text of an agent's terminal: the tail of its zmx session scrollback as plain text (what the screen shows plus history), trailing blank lines removed. Rows the terminal soft-wrapped read as one line: on the live screen by the terminal's own wrap flags; above it (where the history carries none) a row that fills the terminal's width and ends in text joins the next, unless it is a separator padded to the width, such as pytest's `==== FAILURES ====`, or the next row starts with the same word (pytest's `FAILED …` rows, cut at the width). Inline images (kitty graphics placeholders) read as one `[image]` line. With `block`: the output of a command the terminal's shell finished (`"last"` or -1, -2 the one before; from Ghostty's shell-integration prompt marks and the commands easl saw finish since it attached), with `command` saying what ran; a command-block mention names the `block` that reads it whole. With `final: true`, instead the agent's last answer: the final assistant message of its last finished turn, as its integration reported it (omp, Codex, Claude Code, Gemini CLI; not opencode). It fails with `unavailable` while the agent is in a turn (or hasn't started the one `agent.prompt` sent), and when none is known: never reported, or the turn was interrupted. Answers are saved with the board, so they outlast a restart. */
    read(params: AgentReadParams): Promise<AgentReadResult>;
  };
  follow: {
    /** Report a file location an agent just read, edited, or wrote; re-aims that terminal's follow tile, creating it in a free spot near the terminal (unless the user is working in it, which holds re-aims for ~10 s). Ignored while the terminal's `props.follow` is false, and for files outside the board root, the terminal's cwd, and the other worktrees of their repositories (a worktree file keeps its absolute path and its own gutter), scratch files in the temp directory, missing files, images, PDFs, archives, and other binaries: the tile keeps its last real file. */
    report(params: FollowReportParams): Promise<FollowReportResult>;
  };
  view: {
    /** Raise an attention marker pointing at an object (one per object; raising again replaces its message), or remove it with `clear: true`. A marker belongs to the caller's turn: raising one clears the markers the same caller raised in earlier turns (a turn starts when its lifecycle goes to working from idle, done, or no state; answering an approval, blocked → working, continues the turn); markers from this turn stay. The user seeing the object also clears it. Unseen markers are stored with the board and survive app restarts; deleting the object removes its marker. Never moves the user's viewport. */
    attention(params: ViewAttentionParams): Promise<ViewAttentionResult>;
    /** What the user is looking at right now, without pixels: the visible board rect and zoom, the prompt-target terminal, the tile with keyboard focus, the selection, whether the window is visible on screen, and its appearance (dark or light). */
    get(params?: ViewGetParams): Promise<ViewGetResult>;
    /** Open a web address the way a ⌘-click on it in the caller's terminal does: an http or https URL shows in a browser tile beside the caller, and a tile already showing that address (compared by scheme, host, port, path, query and fragment, so `HTTP://Example.com:80` is `http://example.com/`) is reused (`existing: true`) instead of a duplicate. The user's view pans the least that shows the tile, never so far that the caller's terminal leaves view. Keyboard focus stays where it was: the tile is selected unless that would take the keyboard from another tile than a terminal (a note being edited, a page or code rows being typed in), which keeps it and its selection. Anything but http(s) is `invalid_params`: hand other schemes to the system (`/usr/bin/open`). The `bin/open` shim and `$BROWSER` in a terminal tile call this. */
    open_url(params: ViewOpenUrlParams): Promise<ViewOpenUrlResult>;
    /** Render part of the board offscreen at a fixed scale, independent of the user's viewport (never moves it). `target` is an object id, a list of ids, or a board rect; ids render the board region under their outlines (with whatever overlaps them) and the whole route of every arrow between two of them, `full` draws those tiles' whole content (note/HTML scroll height; code: all of its range, scrolled to it and wrapped at its tile's width) extending below/right of their frames. Waits until content has painted (up to `timeoutMs`) and reports per-object state instead of returning blanks. App chrome (toolbar, tray, hints, selection rings, attention markers) is never drawn. A tile draws as on screen: its title bar at 1× (showing its content zoom's % when not 100%), its content at its `zoom` inside the frame. */
    render(params: ViewRenderParams): Promise<ViewRenderResult>;
    /** The board's window as the user sees it right now (viewport, tiles, toolbar, tray), with the viewport it shows. Terminal tiles are drawn from their session text. To look at something regardless of where the user is, use view.render. */
    snapshot(params?: ViewSnapshotParams): Promise<ViewSnapshotResult>;
  };
  events: {
    /** Turn this connection into an event stream. Events: object.created, object.updated, object.deleted, tray.changed, agent.lifecycle, follow.updated, attention.changed ({id, active, message?, raisedBy?}). */
    subscribe(params?: EventsSubscribeParams): Promise<EventsSubscribeResult>;
  };
}

/** Params a client fills from its tile (`caller`) and board when the call omits them, with the env var each defaults from. */
export const ENV_DEFAULTS: Record<string, string> = {"caller":"EASL_TILE_ID","board":"EASL_BOARD_ID"};

/** `call` receives the method's auto-filled param names (keys of ENV_DEFAULTS it accepts). */
export function bindMethods(call: (method: string, params: object, envKeys: string[]) => Promise<unknown>): CanvasApi {
  return {
    system: {
      ping: (params?: SystemPingParams) => call("system.ping", params ?? {}, []) as Promise<SystemPingResult>,
    },
    app: {
      metrics: (params?: AppMetricsParams) => call("app.metrics", params ?? {}, []) as Promise<AppMetricsResult>,
    },
    board: {
      get: (params?: BoardGetParams) => call("board.get", params ?? {}, ["board"]) as Promise<BoardGetResult>,
      history: (params?: BoardHistoryParams) => call("board.history", params ?? {}, ["board"]) as Promise<BoardHistoryResult>,
      list: (params?: BoardListParams) => call("board.list", params ?? {}, []) as Promise<BoardListResult>,
      open: (params: BoardOpenParams) => call("board.open", params ?? {}, []) as Promise<BoardOpenResult>,
      export: (params?: BoardExportParams) => call("board.export", params ?? {}, ["board"]) as Promise<BoardExportResult>,
    },
    object: {
      get: (params: ObjectGetParams) => call("object.get", params ?? {}, []) as Promise<ObjectGetResult>,
      find: (params?: ObjectFindParams) => call("object.find", params ?? {}, ["board"]) as Promise<ObjectFindResult>,
      create: (params: ObjectCreateParams) => call("object.create", params ?? {}, ["board","caller"]) as Promise<ObjectCreateResult>,
      update: (params: ObjectUpdateParams) => call("object.update", params ?? {}, ["caller"]) as Promise<ObjectUpdateResult>,
      upsert: (params: ObjectUpsertParams) => call("object.upsert", params ?? {}, ["board","caller"]) as Promise<ObjectUpsertResult>,
      delete: (params: ObjectDeleteParams) => call("object.delete", params ?? {}, ["caller"]) as Promise<ObjectDeleteResult>,
      measure: (params: ObjectMeasureParams) => call("object.measure", params ?? {}, ["board","caller"]) as Promise<ObjectMeasureResult>,
      reload: (params: ObjectReloadParams) => call("object.reload", params ?? {}, ["caller"]) as Promise<ObjectReloadResult>,
      batch: (params: ObjectBatchParams) => call("object.batch", params ?? {}, ["board","caller"]) as Promise<ObjectBatchResult>,
    },
    layout: {
      place: (params: LayoutPlaceParams) => call("layout.place", params ?? {}, ["caller"]) as Promise<LayoutPlaceResult>,
      stack: (params: LayoutStackParams) => call("layout.stack", params ?? {}, ["caller"]) as Promise<LayoutStackResult>,
      translate: (params: LayoutTranslateParams) => call("layout.translate", params ?? {}, ["caller"]) as Promise<LayoutTranslateResult>,
      grid: (params: LayoutGridParams) => call("layout.grid", params ?? {}, ["caller"]) as Promise<LayoutGridResult>,
      check: (params?: LayoutCheckParams) => call("layout.check", params ?? {}, ["board","caller"]) as Promise<LayoutCheckResult>,
    },
    tray: {
      list: (params?: TrayListParams) => call("tray.list", params ?? {}, ["board"]) as Promise<TrayListResult>,
      stage: (params: TrayStageParams) => call("tray.stage", params ?? {}, ["board"]) as Promise<TrayStageResult>,
      unstage: (params: TrayUnstageParams) => call("tray.unstage", params ?? {}, []) as Promise<TrayUnstageResult>,
      drain: (params?: TrayDrainParams) => call("tray.drain", params ?? {}, ["board","caller"]) as Promise<TrayDrainResult>,
      commit: (params: TrayCommitParams) => call("tray.commit", params ?? {}, ["board"]) as Promise<TrayCommitResult>,
    },
    agent: {
      report: (params: AgentReportParams) => call("agent.report", params ?? {}, []) as Promise<AgentReportResult>,
      report_session: (params: AgentReportSessionParams) => call("agent.report_session", params ?? {}, []) as Promise<AgentReportSessionResult>,
      release: (params: AgentReleaseParams) => call("agent.release", params ?? {}, []) as Promise<AgentReleaseResult>,
      list: (params?: AgentListParams) => call("agent.list", params ?? {}, []) as Promise<AgentListResult>,
      prompt: (params: AgentPromptParams) => call("agent.prompt", params ?? {}, ["caller"]) as Promise<AgentPromptResult>,
      wait: (params: AgentWaitParams) => call("agent.wait", params ?? {}, []) as Promise<AgentWaitResult>,
      read: (params: AgentReadParams) => call("agent.read", params ?? {}, []) as Promise<AgentReadResult>,
    },
    follow: {
      report: (params: FollowReportParams) => call("follow.report", params ?? {}, []) as Promise<FollowReportResult>,
    },
    view: {
      attention: (params: ViewAttentionParams) => call("view.attention", params ?? {}, ["caller"]) as Promise<ViewAttentionResult>,
      get: (params?: ViewGetParams) => call("view.get", params ?? {}, ["board"]) as Promise<ViewGetResult>,
      open_url: (params: ViewOpenUrlParams) => call("view.open_url", params ?? {}, ["board","caller"]) as Promise<ViewOpenUrlResult>,
      render: (params: ViewRenderParams) => call("view.render", params ?? {}, ["board"]) as Promise<ViewRenderResult>,
      snapshot: (params?: ViewSnapshotParams) => call("view.snapshot", params ?? {}, ["board"]) as Promise<ViewSnapshotResult>,
    },
    events: {
      subscribe: (params?: EventsSubscribeParams) => call("events.subscribe", params ?? {}, ["board"]) as Promise<EventsSubscribeResult>,
    },
  };
}

export const METHODS = ["system.ping","app.metrics","board.get","board.history","board.list","board.open","board.export","object.get","object.find","object.create","object.update","object.upsert","object.delete","object.measure","object.reload","object.batch","layout.place","layout.stack","layout.translate","layout.grid","layout.check","tray.list","tray.stage","tray.unstage","tray.drain","tray.commit","agent.report","agent.report_session","agent.release","agent.list","agent.prompt","agent.wait","agent.read","follow.report","view.attention","view.get","view.open_url","view.render","view.snapshot","events.subscribe"] as const;

/** Reads the client re-sends when the connection drops after sending (the app restarted), with `timeoutMs` reduced by the time already spent. */
export const RESEND_METHODS: readonly string[] = ["agent.wait"];
